'use server';

import { ai } from '@/ai/genkit';
import { z } from 'genkit';

/**
 * SCHEMI DI VALIDAZIONE
 */
const MG30PresetInputSchema = z.object({
  description: z.string().describe('Descrizione del suono desiderato'),
});

const MG30PresetOutputSchema = z.object({
  presetName: z.string(),
  explanation: z.string(),
  ampModel: z.string(),
  effects: z.array(z.object({
    type: z.string(),
    model: z.string()
  })),
});

export type MG30PresetInput = z.infer<typeof MG30PresetInputSchema>;
export type MG30PresetOutput = z.infer<typeof MG30PresetOutputSchema>;

// Definiamo il Prompt come nel tuo file funzionante
const mg30PresetPrompt = ai.definePrompt(
  {
    name: 'mg30PresetPrompt',
    model: 'googleai/gemini-2.0-flash-lite', 
    input: { schema: MG30PresetInputSchema },
    output: { schema: MG30PresetOutputSchema },
    config: {
      temperature: 0.7,
      // Forziamo il formato JSON per evitare errori di parsing
      responseMimeType: 'application/json',
    },
    system: `Sei un esperto NUX MG-30. Genera un preset basandoti sulla richiesta.
    Usa ESCLUSIVAMENTE i nomi dei modelli dell'hardware MG-30.
    Rispondi SEMPRE in formato JSON con: presetName, explanation, ampModel, effects.`,
  },
  `Crea un preset per questo suono: {{description}}`
);

/**
 * Questa è la funzione che il tuo frontend deve chiamare.
 */
export async function generateMG30Preset(input: MG30PresetInput): Promise<MG30PresetOutput> {
  try {
    const { output } = await mg30PresetPrompt(input);
    
    if (!output) {
       throw new Error('L\'AI ha risposto con un formato vuoto.');
    }
    
    return output;
  } catch (error) {
    console.error("Errore generazione preset:", error);
    // Fallback sicuro per non rompere il frontend
    return {
      presetName: "Default Tone",
      explanation: "Errore durante la generazione. Verifica i log del server.",
      ampModel: "Brit 800",
      effects: []
    };
  }
}